//! Reference parity tests against fixtures generated by `tools/parity.py`
//! from the Hugging Face `tokenizers`/`transformers` implementations.

use std::path::{Path, PathBuf};

use burn::backend::NdArray;
use clearscroll_engine::embedder::Embedder;
use clearscroll_engine::tokenizer::WordPieceTokenizer;
use serde_json::Value;

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn fixture(name: &str) -> Value {
    let path = repo().join("tests/fixtures").join(name);
    serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap()
}

#[test]
fn tokenizer_matches_hf_reference() {
    let vocab = std::fs::read_to_string(repo().join("model/vocab.txt")).unwrap();
    let tok = WordPieceTokenizer::from_vocab(&vocab).unwrap();
    let fx = fixture("tokenizer_parity.json");
    let max_len = fx["max_len"].as_u64().unwrap() as usize;
    let cases = fx["cases"].as_array().unwrap();
    assert!(cases.len() >= 20);
    for case in cases {
        let text = case["text"].as_str().unwrap();
        let want: Vec<u32> = case["ids"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap() as u32)
            .collect();
        assert_eq!(tok.encode(text, max_len), want, "text: {text:?}");
    }
}

/// Exported weights are not committed (16–86 MiB). The test is skipped when
/// they are absent unless CLEARSCROLL_REQUIRE_MODEL names the model (comma-
/// separated list, or "all"), in which case absence is a failure. CI sets it
/// for the model it prepares, so the check can never be skipped silently.
fn model_artifacts(model: &str) -> Option<(Vec<u8>, String)> {
    let dir: &Path = &repo().join("build/models").join(model);
    match (
        std::fs::read(dir.join("weights.bin")),
        std::fs::read_to_string(dir.join("vocab.txt")),
    ) {
        (Ok(w), Ok(v)) => Some((w, v)),
        _ if required(model) => {
            panic!(
                "CLEARSCROLL_REQUIRE_MODEL requires {model} but {} has no artifacts",
                dir.display()
            )
        }
        _ => {
            eprintln!(
                "SKIPPED: {} not prepared (run tools/prepare_model.py --model {model})",
                dir.display()
            );
            None
        }
    }
}

fn required(model: &str) -> bool {
    std::env::var("CLEARSCROLL_REQUIRE_MODEL")
        .map(|v| v.split(',').any(|m| m.trim() == model || m.trim() == "all"))
        .unwrap_or(false)
}

fn check_embeddings(model: &str) {
    let Some((weights, vocab)) = model_artifacts(model) else {
        return;
    };
    let fx = fixture(&format!("embedding_parity_{model}.json"));
    let tol = fx["max_abs_tol"].as_f64().unwrap() as f32;
    let cases = fx["cases"].as_array().unwrap();
    let texts: Vec<String> = cases
        .iter()
        .map(|c| c["text"].as_str().unwrap().to_string())
        .collect();

    let embedder = Embedder::<NdArray>::new(&weights, &vocab, Default::default()).unwrap();
    let flat = embedder.embed_sync(&texts).unwrap();
    for (i, case) in cases.iter().enumerate() {
        let want: Vec<f32> = case["embedding"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap() as f32)
            .collect();
        let got = &flat[i * embedder.dim()..(i + 1) * embedder.dim()];
        let max_diff = got
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs())
            .fold(0.0f32, f32::max);
        assert!(
            max_diff <= tol,
            "{model} text {i} {:?}: max |Δ| {max_diff} > {tol}",
            texts[i]
        );
    }
}

#[test]
fn bert_tiny_embeddings_match_reference() {
    check_embeddings("bert-tiny");
}

#[test]
fn minilm_l6_embeddings_match_reference() {
    check_embeddings("minilm-l6");
}

/// f16-stored weights against PyTorch with identically rounded weights:
/// checks the half-precision decoder and the model exactly.
#[test]
fn minilm_l6_f16_embeddings_match_reference() {
    check_embeddings("minilm-l6-f16");
}
